const state={page:'Dashboard',clinic:localStorage.getItem('dentiva.clinic')||''};
const nav=[['◈','Dashboard'],['♙','Patients'],['▣','Appointments'],['⌁','Clinical'],['▤','Billing'],['◫','Finance'],['♧','Staff'],['▥','Reports']];
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');
function shell(){document.querySelector('#app').innerHTML=`<div class="shell"><aside class="rail"><div class="brand"><img src="assets/dentiva.svg"><div><strong>DENTIVA</strong><small>CLINIC OS</small></div></div><div class="nav-group">Workspace</div>${nav.map(([i,n])=>`<button class="nav ${state.page===n?'active':''}" data-page="${n}"><span class="ico">${i}</span><span>${n}</span></button>`).join('')}<div class="nav-group">System</div><button class="nav" data-page="Settings"><span class="ico">⚙</span><span>Settings</span></button><button class="nav" data-page="About"><span class="ico">ⓘ</span><span>About Dentiva</span></button><div class="rail-footer">Local workspace<br><span style="color:#5fb8ae">●</span> Secure & offline</div></aside><main class="main"><header class="topbar"><div class="crumb">Dentiva <span style="margin:0 8px;color:#cbd5dc">/</span> <b>${state.page}</b></div><div class="top-actions"><input class="global-search" placeholder="⌕  Search patients" aria-label="Search patients"><div class="avatar">${state.clinic?initials(state.clinic):'DR'}</div></div></header><section class="content">${view()}</section></main></div>`;document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>{state.page=x.dataset.page;shell()});if(!state.clinic)setTimeout(setup,120)}
function view(){if(state.page!=='Dashboard')return `<div class="hero"><div><div class="eyebrow">${state.page}</div><h1>${state.page}</h1><p>This workspace is ready for your clinic records.</p></div><button class="btn">＋ New ${state.page==='Patients'?'patient':'record'}</button></div><div class="card empty"><div style="font-size:32px;color:var(--teal);margin-bottom:12px">◎</div><b>No records yet</b>Your clinic workspace is empty. Add your first record to begin.</div>`;return `<div class="hero"><div><div class="eyebrow">Monday, 21 September 2026</div><h1>Good morning${state.clinic?', '+state.clinic:''}.</h1><p>Here is your clinical overview for today.</p></div><button class="btn">＋ New patient</button></div><div class="cards">${[['♙','Today’s patients','0','No appointments yet'],['✦','New patients','0','Ready for your first registration'],['◷','Follow-ups due','0','Nothing requires attention'],['▤','Completed visits','0','Your daily activity']].map(x=>`<div class="card metric"><div><div class="label">${x[1]}</div><h2>${x[2]}</h2><div class="delta">${x[3]}</div></div><div class="metric-icon">${x[0]}</div></div>`).join('')}</div><div class="grid"><div class="card"><div class="card-title"><h3>Today’s appointments</h3><button class="link">Open calendar →</button></div><div class="empty"><div style="font-size:30px;color:#a9c8d1;margin-bottom:10px">◷</div><b>Your schedule is clear</b>No appointments have been added for today.</div></div><div class="card queue"><div class="card-title"><h3>Today’s queue</h3><button class="link">Manage queue →</button></div><div class="now"><small>Now serving</small><h2>No patient in consultation</h2><p>Add an appointment to start your queue.</p></div><div class="queue-stats"><div class="queue-stat"><b>0</b><span>Waiting</span></div><div class="queue-stat"><b>0</b><span>Completed</span></div><div class="queue-stat"><b>0</b><span>Remaining</span></div></div></div><div class="card"><div class="card-title"><h3>Quick actions</h3></div><div class="quick"><button><span>＋</span>New patient</button><button><span>◷</span>Appointment</button><button><span>⌁</span>Start a visit</button><button><span>▤</span>Create invoice</button></div></div><div class="card"><div class="card-title"><h3>Recent patients</h3><button class="link">View all →</button></div><div class="empty" style="padding:28px"><b>No patients registered</b>Your patient list will appear here.</div></div></div>`}
function setup(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-back"><div class="modal"><div class="eyebrow">Welcome to Dentiva</div><h2>Set up your clinic workspace</h2><p>Let’s get the essentials ready. You can complete the rest of your clinic settings at any time.</p><div class="field"><label>Clinic name</label><input id="clinic" placeholder="e.g. Your clinic name" autofocus></div><div class="modal-actions"><button class="btn ghost" id="skip">Set up later</button><button class="btn" id="save">Continue →</button></div></div></div>`);document.querySelector('#save').onclick=()=>{const v=document.querySelector('#clinic').value.trim();if(v){localStorage.setItem('dentiva.clinic',v);state.clinic=v}document.querySelector('.modal-back').remove();shell()};document.querySelector('#skip').onclick=()=>document.querySelector('.modal-back').remove()}
shell();
